const LINES = [];   // { pts, op, a, b, dim (beat it turns into a thin ghost), off, thin, dash }
const DOTS = [];    // { at, a, off, r }
const GROUPS = [];  // label groups: { a, off, v, items: [{ text, at | xy(v), kind, a }], avoid: [lonlat] }
